const webhook = $('Document Extract Webhook').first().json;
const input = webhook.body ?? webhook;
const response = $json;
function getOutputText(value) {
  if (typeof value.output_text === 'string') return value.output_text;
  const output = Array.isArray(value.output) ? value.output : [];
  for (const item of output) {
    const content = Array.isArray(item.content) ? item.content : [];
    for (const part of content) {
      if (typeof part.text === 'string') return part.text;
    }
  }
  return '';
}
const text = getOutputText(response);
if (!text) throw new Error('OpenAI did not return extractable text.');
const parsed = JSON.parse(text);
const extracted = {
  document_type: parsed.document_type ?? '',
  vendor_name: parsed.vendor_name ?? '',
  document_number: parsed.document_number ?? '',
  document_date: parsed.document_date ?? '',
  currency: parsed.currency ?? '',
  subtotal: parsed.subtotal ?? '',
  tax: parsed.tax ?? '',
  total: parsed.total ?? '',
  payment_method: parsed.payment_method ?? '',
  confidence: Number(parsed.confidence ?? 0),
  notes: parsed.notes ?? ''
};
return [{ json: { status: 'extracted', original_file_name: input.original_file_name ?? '', extracted, warnings: [] } }];
